import assert from 'node:assert/strict';
import { createDraftStore } from './src/draft-store.js';
import { createWorkspace } from './src/workspace.js';

function fakeTimers() {
  let next = 0;
  const jobs = new Map();
  return {
    schedule(callback, delay) { const id = ++next; jobs.set(id, { callback, delay }); return id; },
    cancel(id) { jobs.delete(id); },
    runAll() { while (jobs.size) { const [id, job] = jobs.entries().next().value; jobs.delete(id); job.callback(); } },
    delays() { return [...jobs.values()].map(job => job.delay); },
  };
}
{
  const timers = fakeTimers(), store = createDraftStore({ a: 'old' });
  const events = [], statuses = [];
  const workspace = createWorkspace({ store, timers, renderDocument: () => {}, renderStatus: e => statuses.push(e), onSaved: e => events.push(e) });
  workspace.open('a');
  workspace.edit('one'); workspace.edit('two');
  assert.deepEqual(timers.delays(), [120]);
  assert.equal(store.read('a'), 'old');
  timers.runAll();
  assert.equal(store.read('a'), 'two');
  workspace.edit('three'); workspace.close();
  assert.equal(store.read('a'), 'three');
  assert.deepEqual(events.map(e => e.text), ['two', 'three']);
  assert.deepEqual(statuses.map(e => e.text), ['two']);
}
{
  const timers = fakeTimers(), store = createDraftStore({ a: 'A', b: 'B', c: 'C' });
  let workspace;
  workspace = createWorkspace({ store, timers, renderDocument: () => {}, renderStatus: () => {}, onSaved(event) { if (event.id === 'a') workspace.open('c'); } });
  workspace.open('a'); workspace.edit('new A'); workspace.open('b');
  assert.equal(store.read('a'), 'new A');
  workspace.edit('new C'); workspace.close();
  assert.equal(store.read('c'), 'new C');
}
console.log('autosave assertions passed');
